import { createContext, useContext, useState, ReactNode } from 'react';

interface AccordionContextValue {
  expandedId: string | null;
  setExpandedId: (id: string | null) => void;
}

const AccordionContext = createContext<AccordionContextValue | null>(null);

function useAccordionContext() {
  const context = useContext(AccordionContext);
  if (!context) throw new Error('Accordion sub-components must be used inside <Accordion>');
  return context;
}

function Accordion({ children }: { children: ReactNode }) {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  return (
    <AccordionContext.Provider value={{ expandedId, setExpandedId }}>
      {children}
    </AccordionContext.Provider>
  );
}

function Item({ children }: { children: ReactNode }) {
  return <div>{children}</div>;
}

function Header({ id, children }: { id: string; children: ReactNode }) {
  const { expandedId, setExpandedId } = useAccordionContext();
  return (
    <button onClick={() => setExpandedId(expandedId === id ? null : id)}>
      {children}
    </button>
  );
}

function Content({ id, children }: { id: string; children: ReactNode }) {
  const { expandedId } = useAccordionContext();
  if (expandedId !== id) return null;
  return <div>{children}</div>;
}

Accordion.Item = Item;
Accordion.Header = Header;
Accordion.Content = Content;

export default Accordion;

sections.content:
Extracting Module 6, lesson 5's repeated loading/error/data fetching pattern into a reusable custom hook:

function useFetch<T>(url: string) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setLoading(true);
    setError(null);

    async function load() {
      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Request failed with status ${response.status}`);
        const json: T = await response.json();
        setData(json);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setLoading(false);
      }
    }

    load();
  }, [url]);

  return { data, loading, error };
}

// Used in ANY component needing this exact pattern, with zero duplication:
function UserProfile({ userId }: { userId: number }) {
  const { data: user, loading, error } = useFetch<User>(`/api/users/${userId}`);

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error}</p>;
  return <h2>{user?.name}</h2>;
}

