function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const stored = localStorage.getItem(key);
      return stored ? JSON.parse(stored) : initialValue;
    } catch {
      return initialValue;
    }
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue] as const;
}

// Used exactly like useState, but automatically persisted -
// directly replacing Module 5's manual localStorage read/write calls
function TodoApp() {
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);

  function addTask(title: string) {
    setTasks([...tasks, { id: Date.now(), title, completed: false }]);
    // no manual localStorage.setItem call needed anywhere here -
    // the hook's own useEffect handles persistence automatically
  }

  return (/* ... render tasks ... */ null);
}

