import { useState, useEffect } from 'react';

// TODO: write useDebounce<T>(value: T, delayMs: number): T
// It should return a debounced value that only updates after delayMs
// has passed without the input value changing again

// TODO: use it in a SearchBox component, logging the debounced value
// in a useEffect whenever it actually changes

codingChallenge.solutionExample:
import { useState, useEffect } from 'react';

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setDebouncedValue(value);
    }, delayMs);

    return () => clearTimeout(timeoutId); // cleanup: cancel if value changes again before delay
  }, [value, delayMs]);

  return debouncedValue;
}

function SearchBox() {
  const [term, setTerm] = useState('');
  const debouncedTerm = useDebounce(term, 500);

  useEffect(() => {
    if (debouncedTerm) {
      console.log('Searching for:', debouncedTerm);
    }
  }, [debouncedTerm]);

  return <input value={term} onChange={(e) => setTerm(e.target.value)} />;
}

