Instead of one large AppContext combining everything:

// AVOID: one large, combined context
interface AppContextValue {
  user: User | null;
  theme: 'light' | 'dark';
  cartItems: CartItem[];
  // any change to ANY of these re-renders every consumer of AppContext
}

Split into focused, separately-scoped contexts:

// AuthContext.tsx
const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  // ... login/logout functions ...
  return <AuthContext.Provider value={{ user, login, logout }}>{children}</AuthContext.Provider>;
}

// Pairing the context with a custom hook (lesson 2), directly extending
// Module 10, lesson 3's useAuth into a more deliberate, reusable pattern
export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used inside AuthProvider');
  return context;
}

// ThemeContext.tsx - completely separate, independently-updating context
const ThemeContext = createContext<ThemeContextValue | null>(null);
export function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useTheme must be used inside ThemeProvider');
  return context;
}

