// COMBINED CONTEXT - changing theme re-renders EVERY consumer,
// including ones that only care about user
function UserGreeting() {
  const { user } = useContext(AppContext)!; // re-renders even when
                                               // only theme changed,
                                               // despite never using theme
  return <p>Hello, {user?.name}</p>;
}

// SPLIT CONTEXTS - UserGreeting only re-renders when AuthContext
// itself actually changes, completely unaffected by theme changes
function UserGreeting() {
  const { user } = useAuth(); // only depends on AuthContext specifically
  return <p>Hello, {user?.name}</p>;
}

function ThemeToggle() {
  const { theme, setTheme } = useTheme(); // only depends on ThemeContext
  return (
    <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
      Toggle theme
    </button>
  );
}

// Clicking ThemeToggle's button now ONLY re-renders components
// consuming ThemeContext - UserGreeting is completely unaffected,
// since it never calls useTheme or useContext(ThemeContext) at all

