React.memo — wraps a component, skipping its re-render if its props are shallowly equal to the previous render's props:

const ProjectCard = React.memo(function ProjectCard({ title, description }: ProjectCardProps) {
  return <div><h3>{title}</h3><p>{description}</p></div>;
});

useMemo — skips recalculating an expensive value unless its dependencies change:

const sortedProjects = useMemo(() => {
  return [...projects].sort((a, b) => a.name.localeCompare(b.name));
}, [projects]);

useCallback — skips recreating a function unless its dependencies change, most useful when that function is passed as a prop to a React.memo-wrapped child:

const handleDelete = useCallback((id: string) => {
  setProjects((prev) => prev.filter((p) => p.id !== id));
}, []); // empty dependency array - this function never actually needs to change

