// STEP 1 - MEASURE: Using React DevTools Profiler, recording a parent
// re-render (e.g. typing in an unrelated search box) reveals that EVERY
// ProjectCard child re-renders too, even though their own props never
// actually changed. This is the genuine, evidence-based signal to act on.

// THE PROBLEM, before any fix:
function ProjectList({ projects }: { projects: Project[] }) {
  const [searchTerm, setSearchTerm] = useState('');

  function handleDelete(id: string) {
    // ... delete logic ...
  }

  return (
    <div>
      <input value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      {projects.map((project) => (
        <ProjectCard key={project.id} project={project} onDelete={handleDelete} />
        // handleDelete is a NEW function reference every single render,
        // since typing in the search box re-renders ProjectList itself
      ))}
    </div>
  );
}

// STEP 2 - THE CORRECTLY PAIRED FIX:
const ProjectCard = React.memo(function ProjectCard({ project, onDelete }: ProjectCardProps) {
  return (
    <div>
      <h3>{project.name}</h3>
      <button onClick={() => onDelete(project.id)}>Delete</button>
    </div>
  );
});

function ProjectList({ projects }: { projects: Project[] }) {
  const [searchTerm, setSearchTerm] = useState('');

  const handleDelete = useCallback((id: string) => {
    // ... delete logic ...
  }, []); // stable reference - now genuinely useful, since ProjectCard is memoized

  return (
    <div>
      <input value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
      {projects.map((project) => (
        <ProjectCard key={project.id} project={project} onDelete={handleDelete} />
      ))}
    </div>
  );
}

